using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal static class ForkModelRemapProof
{
    private static readonly FieldInfo Kinds = typeof(PredictionForkContext)
        .GetField("_modelMappingKinds", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static long _queries, _noModels, _noCards, _mapped, _self;

    private static void Observe(PredictionForkContext __instance, AbstractModel value, AbstractModel __result)
    {
        AbstractModel expected = __instance.RemapOrSelf(value);
        if (!ReferenceEquals(expected, __result))
            throw new InvalidOperationException("Actual Fork listener remapping differs from original identity map.");
        Interlocked.Increment(ref _queries);
        byte kinds = (byte)Kinds.GetValue(__instance)!;
        if (kinds == 0) Interlocked.Increment(ref _noModels);
        else if (value is CardModel && (kinds & 2) == 0) Interlocked.Increment(ref _noCards);
        if (ReferenceEquals(value, __result)) Interlocked.Increment(ref _self);
        else Interlocked.Increment(ref _mapped);
    }

    internal static IDisposable VerifyAndObserve(CombatState live, CombatPredictionSimulator parent,
        Player player, Func<CombatPredictionSimulator, string> stamp, Action<string> record)
    {
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        string parentBefore = stamp(parent);
        AbstractModel[] models = ModelDb.All.ToArray();
        CardModel card = ModelDb.Card<StrikeIronclad>();
        PowerModel power = ModelDb.Power<StrengthPower>();
        CardModel unknown = Unknown();
        AbstractModel[] inputs = [.. models, unknown];
        int comparisons = 0;
        void Check(PredictionForkContext context)
        {
            foreach (AbstractModel model in inputs)
            {
                if (!ReferenceEquals(context.RemapOrSelf(model), context.RemapCachedModelOrSelf(model)))
                    throw new InvalidOperationException("Registration-derived negative answer differs.");
                comparisons++;
            }
        }
        foreach (int count in new[] { 0, 1, 40, 63, 64, 65, 128, 1024 })
        {
            using PredictionForkContext context = new();
            for (int i = 0; i < count; i++) context.Register(new object(), new object());
            Check(context);
            // Runtime source type, rather than declared generic type or target type, owns eligibility.
            AbstractModel otherPower = (AbstractModel)RuntimeHelpers.GetUninitializedObject(power.GetType());
            context.Register<object>(power, otherPower);
            Check(context);
            context.Register<AbstractModel>(unknown, card);
            Check(context);
            AbstractModel otherCard = (AbstractModel)RuntimeHelpers.GetUninitializedObject(card.GetType());
            context.Register<object>(card, otherCard);
            context.Register<AbstractModel>(card, otherCard);
            context.Register<AbstractModel>(card, card);
            Check(context);
            try
            {
                context.Register<AbstractModel>(card, unknown);
                throw new InvalidOperationException("Duplicate remapping was accepted.");
            }
            catch (InvalidOperationException error) when (error.Message.EndsWith("was forked twice.")) { }
            Check(context);
        }
        using (PredictionForkContext invalidCast = new())
        {
            invalidCast.Register<object>(card, new object());
            foreach (bool useFast in new[] { false, true })
            {
                try
                {
                    _ = useFast ? invalidCast.RemapCachedModelOrSelf(card) : invalidCast.RemapOrSelf<AbstractModel>(card);
                    throw new InvalidOperationException("Invalid target type was accepted.");
                }
                catch (InvalidCastException) { }
            }
        }
        // A non-card source mapped to a card does not create a mapping for that card identity.
        using (PredictionForkContext sourceKinds = new())
        {
            sourceKinds.Register<AbstractModel>(power, unknown);
            Check(sourceKinds);
        }

        var method = typeof(PredictionForkContext).GetMethod(nameof(PredictionForkContext.RemapCachedModelOrSelf))!;
        var postfix = typeof(ForkModelRemapProof).GetMethod(nameof(Observe), BindingFlags.Static | BindingFlags.NonPublic)!;
        Harmony harmony = new("CombatSolver.Tests.ForkModelNegativeMap");
        harmony.Patch(method, postfix: new HarmonyMethod(postfix));
        try
        {
            int parallel = 0;
            Parallel.For(0, 16, index =>
            {
                using IDisposable isolation = SimulationNotificationIsolation.Enter();
                CombatPredictionSimulator child;
                lock (parent) child = parent.Fork();
                if (stamp(child) != parentBefore)
                    throw new InvalidOperationException("Fork changed full state, history or RNG.");
                child.State.GetPlayerCombatState(player).Hand.Cards[0].MutablePreview.BaseReplayCount = index + 1;
                CombatPredictionSimulator descendant = child.Fork();
                if (stamp(descendant) != stamp(child))
                    throw new InvalidOperationException("Two-generation fork after COW differs.");
                Interlocked.Increment(ref parallel);
            });
            if (stamp(parent) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
                throw new InvalidOperationException("Mapping metadata changed parent/live state.");
            record("ForkModelNegativeMap:MetadataOracle:" + JsonSerializer.Serialize(new
            {
                models = models.Length, unknownModels = 1, comparisons, parallel,
                scope = "Empty/model-free/mixed mappings; thresholds; generic aliases; late registration; duplicate/self registration; invalid casts; unknown type; two-generation COW; full state/history/RNG and parent/live isolation."
            }));
            return new Scope(harmony, method, postfix, record);
        }
        catch
        {
            harmony.Unpatch(method, postfix);
            throw;
        }
    }

    private sealed class Scope(Harmony harmony, MethodInfo method, MethodInfo postfix, Action<string> record) : IDisposable
    {
        public void Dispose()
        {
            harmony.Unpatch(method, postfix);
            if (_queries == 0) throw new InvalidOperationException("Actual listener remap oracle was not exercised.");
            record("ForkModelNegativeMap:ActualForkOracle:" + JsonSerializer.Serialize(new
            {
                queries = _queries, noModelMappings = _noModels, noCardMappings = _noCards,
                returnedMapped = _mapped, returnedSelf = _self
            }));
        }
    }

    private static CardModel Unknown()
    {
        var assembly = AssemblyBuilder.DefineDynamicAssembly(new AssemblyName("CombatSolver.Tests.ForkMap.Unknown"), AssemblyBuilderAccess.RunAndCollect);
        var type = assembly.DefineDynamicModule("Probe").DefineType("UnknownCard", TypeAttributes.Public | TypeAttributes.Sealed, typeof(CardModel));
        var constructor = type.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, Type.EmptyTypes);
        var il = constructor.GetILGenerator(); il.Emit(OpCodes.Ldnull); il.Emit(OpCodes.Throw);
        return (CardModel)RuntimeHelpers.GetUninitializedObject(type.CreateType()!);
    }
}

