using System.Collections;
using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.Models.Powers;

namespace CombatSolver;

internal static class ForkModelCacheProof
{
    private static readonly Type Joined = typeof(SimulatedCombatState).GetNestedType("ConcatenatedListenerView", BindingFlags.NonPublic)!;
    private static readonly ConstructorInfo JoinedCtor = Joined.GetConstructors(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic).Single();
    private static readonly MethodInfo Method = typeof(SimulatedCombatState).GetMethod("RemapCachedModels", BindingFlags.Static | BindingFlags.NonPublic)!;
    private static readonly Func<IReadOnlyList<AbstractModel>, PredictionForkContext, IReadOnlyList<AbstractModel>> Candidate = Method.CreateDelegate<Func<IReadOnlyList<AbstractModel>, PredictionForkContext, IReadOnlyList<AbstractModel>>>();
    private static long _calls, _whole, _wholeSlots, _slots, _mapped;

    private static bool Known(IReadOnlyList<AbstractModel> source)
        => source.GetType() == typeof(AbstractModel[]) || source.GetType() == typeof(List<AbstractModel>)
            || source.GetType() == Joined && source is ISegmentedModelList view && Known(view.Prefix) && Known(view.Suffix);

    private static void Observe(IReadOnlyList<AbstractModel> source, PredictionForkContext context, IReadOnlyList<AbstractModel> __result)
    {
        int count = source.Count;
        if (__result.Count != count) throw new InvalidOperationException("Actual cached-list remap count differs.");
        bool changed = false;
        for (int i = 0; i < count; i++)
        {
            AbstractModel expected = context.RemapOrSelf(source[i]);
            if (!ReferenceEquals(expected, __result[i])) throw new InvalidOperationException("Actual cached-list remap identity/order differs.");
            if (!ReferenceEquals(expected, source[i])) { changed = true; Interlocked.Increment(ref _mapped); }
        }
        if (!changed && !ReferenceEquals(source, __result)) throw new InvalidOperationException("Unchanged cached snapshot identity differs.");
        Interlocked.Increment(ref _calls); Interlocked.Add(ref _slots, count);
        if (!context.HasModelMappings && Known(source)) { Interlocked.Increment(ref _whole); Interlocked.Add(ref _wholeSlots, count); }
    }

    private static IReadOnlyList<AbstractModel> Join(IReadOnlyList<AbstractModel> a, IReadOnlyList<AbstractModel> b)
        => (IReadOnlyList<AbstractModel>)JoinedCtor.Invoke([a, b]);
    private static IReadOnlyList<AbstractModel> Original(IReadOnlyList<AbstractModel> source, PredictionForkContext context)
    {
        if (source.GetType() == Joined && source is ISegmentedModelList view)
        {
            var a = Original(view.Prefix, context); var b = Original(view.Suffix, context);
            return ReferenceEquals(a, view.Prefix) && ReferenceEquals(b, view.Suffix) ? source : Join(a, b);
        }
        AbstractModel[]? result = null;
        for (int i = 0; i < source.Count; i++)
        {
            AbstractModel mapped = context.RemapOrSelf(source[i]);
            if (ReferenceEquals(mapped, source[i])) continue;
            result ??= source.ToArray(); result[i] = mapped;
        }
        return result ?? source;
    }

    internal static IDisposable VerifyAndObserve(CombatState live, CombatPredictionSimulator parent,
        Player player, Func<CombatPredictionSimulator, string> stamp, Action<string> record)
    {
        string parentBefore = stamp(parent), liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        CardModel card = ModelDb.Card<StrikeIronclad>(); PowerModel power = ModelDb.Power<StrengthPower>();
        AbstractModel otherPower = (AbstractModel)RuntimeHelpers.GetUninitializedObject(power.GetType());
        AbstractModel otherCard = (AbstractModel)RuntimeHelpers.GetUninitializedObject(card.GetType());
        CardModel unknown = Unknown(); int comparisons = 0;
        foreach (int count in new[] { 0, 64, 128 })
        {
            using PredictionForkContext nullMap = new();
            for (int i = 0; i < count; i++) nullMap.Register(new object(), new object());
            nullMap.Register<object>(null!, card);
            if (!nullMap.HasModelMappings || !ReferenceEquals(card, nullMap.RemapCachedModelOrSelf(null!))
                || !ReferenceEquals(nullMap.RemapOrSelf(unknown), nullMap.RemapCachedModelOrSelf(unknown)))
                throw new InvalidOperationException("Null-source registration was incorrectly excluded.");
        }
        foreach (int shape in Enumerable.Range(0, 6))
        foreach (int mode in Enumerable.Range(0, 5))
        {
            using PredictionForkContext a = new(), b = new();
            for (int i = 0; i < 128; i++) { a.Register(new object(), new object()); b.Register(new object(), new object()); }
            if (mode == 1) { a.Register<AbstractModel>(power, otherPower); b.Register<AbstractModel>(power, otherPower); }
            if (mode == 2) { a.Register<object>(null!, card); b.Register<object>(null!, card); }
            if (mode == 3) { a.Register<object>(card, otherCard); b.Register<object>(card, otherCard); }
            GetterList? ga = null, gb = null;
            IReadOnlyList<AbstractModel> Build(PredictionForkContext context, out GetterList? getter)
            {
                AbstractModel[] values = [card, power, unknown, null!]; getter = null;
                if (shape == 0) return values;
                if (shape == 1) return values.ToList();
                if (shape == 2) return Join([card], Join(values, new List<AbstractModel> { unknown }));
                if (shape == 3) return new CardModel[] { card, unknown };
                getter = new GetterList(values, mode == 4 ? () => context.Register<AbstractModel>(power, otherPower) : null);
                return shape == 4 ? getter : Join([card], getter);
            }
            var sa = Build(a, out ga); var sb = Build(b, out gb);
            var expected = Original(sa, a); var actual = Candidate(sb, b);
            if (expected.Count != actual.Count || !expected.SequenceEqual(actual, ReferenceEqualityComparer.Instance)
                || ReferenceEquals(expected, sa) != ReferenceEquals(actual, sb))
                throw new InvalidOperationException("Frozen/unknown/nullable cache remapping differs.");
            if (ga is not null && gb is not null && (ga.CountReads != gb.CountReads || ga.IndexReads != gb.IndexReads))
                throw new InvalidOperationException("Unknown source getter/index count differs.");
            comparisons++;
        }
        // Unknown index exceptions must occur after exactly the original access prefix.
        using (PredictionForkContext a = new())
        using (PredictionForkContext b = new())
        {
            GetterList ga = new([card, power], null, throwAtIndexRead: 2);
            GetterList gb = new([card, power], null, throwAtIndexRead: 2);
            foreach (bool fast in new[] { false, true })
            {
                try { _ = fast ? Candidate(gb, b) : Original(ga, a); throw new InvalidOperationException("Missing source failure."); }
                catch (InvalidOperationException error) when (error.Message == "getter-injected") { }
            }
            if (ga.CountReads != gb.CountReads || ga.IndexReads != gb.IndexReads)
                throw new InvalidOperationException("Unknown source exception prefix differs.");
        }
        var postfix = typeof(ForkModelCacheProof).GetMethod(nameof(Observe), BindingFlags.NonPublic | BindingFlags.Static)!;
