using System.Reflection;
using System.Text.Json;
using CombatSolver.Engine.Common;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver;

internal static class ForkMappingProbe
{
    private static readonly FieldInfo Sources = typeof(PredictionForkContext).GetField("_sources", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly FieldInfo Count = typeof(PredictionForkContext).GetField("_count", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly Type Joined = typeof(SimulatedCombatState).GetNestedType("ConcatenatedListenerView", BindingFlags.NonPublic)!;
    private static readonly long[] Calls = new long[4], Slots = new long[4], NonPowerOnlyViews = new long[4], NonPowerSlots = new long[4];
    private static long _unknown;
    static ForkMappingProbe()
    {
        AppDomain.CurrentDomain.ProcessExit += (_, _) => File.WriteAllText(
            Environment.GetEnvironmentVariable("FORK_MAPPING_PROBE_OUTPUT")
                ?? throw new InvalidOperationException("Missing mapping-probe output."),
            JsonSerializer.Serialize(new { scope = "Diagnostic only; recursive helper calls overlap; no performance claim.",
                categories = new[] { "no_model_sources", "power_sources_only", "other_model_source", "null_source" },
                calls = Calls, slots = Slots, nonPowerOnlyViews = NonPowerOnlyViews,
                slotsInNonPowerOnlyViews = NonPowerSlots, unknownCollections = _unknown },
                new JsonSerializerOptions { WriteIndented = true }));
    }
    private static bool Known(IReadOnlyList<AbstractModel> source)
        => source.GetType() == typeof(AbstractModel[]) || source.GetType() == typeof(List<AbstractModel>)
            || source.GetType() == Joined && source is ISegmentedModelList view && Known(view.Prefix) && Known(view.Suffix);
    internal static void Record(IReadOnlyList<AbstractModel> source, PredictionForkContext context)
    {
        if (!Known(source)) { Interlocked.Increment(ref _unknown); return; }
        object[] entries = (object[])Sources.GetValue(context)!;
        int count = (int)Count.GetValue(context)!;
        int category = 0;
        for (int i = 0; i < count; i++)
        {
            if (entries[i] is null) { category = 3; break; }
            if (entries[i] is not AbstractModel) continue;
            if (entries[i] is not PowerModel) category = 2;
            else if (category == 0) category = 1;
        }
        int length = source.Count;
        Interlocked.Increment(ref Calls[category]); Interlocked.Add(ref Slots[category], length);
        bool hasPower = false;
        for (int i = 0; i < length; i++) if (source[i] is PowerModel) { hasPower = true; break; }
        if (!hasPower) { Interlocked.Increment(ref NonPowerOnlyViews[category]); Interlocked.Add(ref NonPowerSlots[category], length); }
    }
}

