 plan[key+"Sha256"]=hashlib.sha256(Path(plan[key]).read_bytes()).hexdigest()
(p/"provenance.json").write_text(json.dumps(plan,indent=2)+"\n")
for scene in plan["roots"]:
 for label in plan["sequence"]:
  name=scene+"-"+label;out=p/name;out.mkdir(exist_ok=True);env=os.environ.copy();env["OFFLINE_HARNESS_COMBATSOLVER_DLL"]=plan["baselineDll"] if label.startswith("A") else plan["candidateDll"]
  for k in list(env):
   if k.startswith("OFFLINE_HARNESS_") and k != "OFFLINE_HARNESS_COMBATSOLVER_DLL" or k.startswith("COMBATSOLVER_VERIFY") or k.startswith("DOTNET_Jit") or k.startswith("COMPlus_Jit") or k in ("DOTNET_PerfMapEnabled","COMBATSOLVER_MEASUREMENT_TRACE"):env.pop(k,None)
  args=["dotnet",plan["host"],"--request",plan["requestDirectory"]+"/"+scene+".json","--label",name,"--out",str(out),"--profile","VeryHigh","--dop","16","--budget-ms","60000","--search-mode","Evaluate","--nodes","25000","--beam","135","--card-branches","72","--pile-branches","42","--hand-branches","54","--enable-no-gc-region","--no-gc-region-budget-gigabytes","16"]
  (out/"command.json").write_text(json.dumps(args,indent=2)+"\n")
  begin=time.monotonic()
  with (out/"launcher.log").open("w") as log:
   child=subprocess.Popen(args,env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
   try:code=child.wait(timeout=plan["processTimeoutSeconds"])
   except subprocess.TimeoutExpired:
    os.killpg(child.pid,signal.SIGTERM);child.wait(timeout=10);raise
  if code:raise RuntimeError(name+" failed: "+str(code))
  d=json.loads((out/"result.json").read_text());assert d["status"]=="Passed",name
  m=d["solverMetrics"];r={"scene":scene,"label":label,"wallSeconds":d["wallSeconds"],"coordinatorMs":m["totalElapsedMilliseconds"],"peakProcessWorkingSetBytes":d["peakProcessWorkingSetBytes"],"workerAllocatedBytes":m["totalWorkerAllocatedBytes"],"quality":{k:m.get(k) for k in ("boundary","projectedBattleHpLost","potionCount","potionUses","score","finalHp","finalEnemyHp","combatEndedTurn","onlyDeathRoutes")},"work":{k:m.get(k) for k in ("totalExpanded","totalTransitions","totalChoiceBranches","maxParallelConcurrency")},"processWallSeconds":time.monotonic()-begin}
  runs.append(r);(p/"runs.json").write_text(json.dumps(runs,indent=2)+"\n");print(name,round(r["wallSeconds"],3),r["quality"]["projectedBattleHpLost"],r["work"]["totalTransitions"],r["peakProcessWorkingSetBytes"],flush=True)
